float2 gradBlur1( float2 domain, float2 d, float3 filter){
float3 dx = ( 2*GetBlur1(domain + float2(1,0)*d) - 2*GetBlur1(domain-float2(1,0)*d) );
float3 dy = ( 2*GetBlur1(domain + float2(0,1)*d) - 2*GetBlur1(domain-float2(0,1)*d) );
return 0.5*float2(dx.x*filter.x + dx.y*filter.y + dx.z*filter.z,
dy.x*filter.x + dy.y*filter.y + dy.z*filter.z)/(filter.x+filter.y+filter.z);
}
shader_body
{
float2 d = texsize.zw*4;
float2 grady = gradBlur1(uv, d, float3(2.3,1.4,0.8));
float2 gradx = gradBlur1(uv + grady*d, d, float3(2.1,1.6,1.2));
float2 uv_green = uv-gradx*d*8;
ret = (0.7 + (grady.x+grady.y))*GetPixel(uv_green-grady*texsize.zw*8).y;
float3 c1 = lerp(0,float3(1.8,2.1,0.1),GetPixel(uv - gradx*d*0).x)*saturate(1-GetPixel(uv).y*2);
ret = lerp(ret,float3(1.35,2.06,1.66), (GetBlur3(saturate(uv_green + grady*texsize.zw*8)).y-1.38*GetPixel(uv_green-grady*texsize.zw*8).y));
ret =  lerp(c1,1,ret);
ret = lerp(ret,float3(1.2,0.7,1.1),saturate(1*GetPixel(uv+grady*d*4 - gradx*d*16).z));
}

